void language(){using namespace penta::runtime;ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/"penta-science-data-regression";std::filesystem::create_directories(options.dataDirectory);options.maxOperations=10000000;auto run=[&](const std::string& source,bool good=true){const auto result=execute(source,{},options);if(good&&!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}expect(result.ok()==good,"science language script");};
 run("record f=fft([1,2,3,4]);record x=ifft(f);assert(norm(x.real-[1;2;3;4])<1e-10);assert(norm(x.imag)<1e-10);assert(abs(variance([1,2,3,4])-5/3)<1e-12);assert(abs(stddev([1,2,3,4],1)-sqrt(1.25))<1e-12);matrix c=covariance([1,2;2,4;3,6]);assert(norm(c-[1,2;2,4],\"fro\")<1e-10);assert(quantile([1,2,3,4],0.5)==2.5);");
 run("record b=bootstrap([1,2,3,4],options(replicates=100,seed=7));record c=bootstrap([1,2,3,4],options(replicates=100,seed=7));assert(norm(b.estimates-c.estimates)==0);record h=histogram([1,2,3,4],[1,2,3,4]);assert(h.included==4);assert(norm(h.counts-[1;1;2])==0);assert(abs(normcdf(0)-0.5)<1e-12);");
 run("real s=stddev([-1e200,1e200]);assert(abs(s/(sqrt(2)*1e200)-1)<1e-14);assert(stddev([-1e200,1e200],1)==1e200);assert(stddev(3,1)==0);real tiny=1e-310;assert(stddev([tiny,tiny])==0);record b=bootstrap([1e308,1e308],options(replicates=32));assert(b.mean==1e308&&b.standard_error==0&&b.lower==1e308&&b.upper==1e308);record t=bootstrap([tiny,tiny],options(replicates=32));assert(t.mean==tiny&&t.standard_error==0);");
 run("record b=bootstrap([-1e200,1e200],options(replicates=32,seed=42,statistic=\"stddev\"));assert(b.standard_error>0&&b.standard_error<2e200);assert(b.lower>=0&&b.upper<2e200);record m=bootstrap([-1e200,1e200],options(replicates=32,seed=42));assert(m.standard_error>0&&m.standard_error<2e200);");
 run("real v=variance([-1e200,1e200]);",false);run("real v=stddev([1]);",false);
 run("record a=sym(\"(a*b)*c\");record b=sym(\"a*(b*c)\");assert(symtext(a)!=symtext(b));record d=symdiff(sym(\"x*x+x/3\"),\"x\");assert(abs(symnumeric(d,options(x=3.0))-19/3)<1e-12);assert(symtext(sym(\"0.1+0.2-0.3\"))==\"0\");record r=analysisrecord(\"test\",options(value=[1,2,3]),options(seed=42,source=\"test-model\"));saveanalysis(\"test.analysis\",r);record restored=loadanalysis(\"test.analysis\",r);assert(norm(restored.data.value-r.data.value)==0);assert(restored.data_hash==r.data_hash);");
 run("record f=fft([1,2,3,4,5,6,7]);record recovered=ifft(f);assert(norm(recovered.real-[1;2;3;4;5;6;7])<1e-10);assert(norm(recovered.imag)<1e-10);");run("real v=variance([1]);",false);run("record s=sym(\"a/b\");",false);run("record p=autocorr([1,1,1]);",false);run("record p=bootstrap([1,2],options(typo=1));",false);
#ifdef PENTA_SOURCE_DIR
 for(const auto* category:{"signal-analysis","statistics","symbolic-algebra","reproducible-analysis"}){const auto path=std::filesystem::path(PENTA_SOURCE_DIR)/"examples"/category/"main.p";std::ifstream stream(path,std::ios::binary);const std::string source((std::istreambuf_iterator<char>(stream)),{});expect(!source.empty(),"science example exists");run(source);}
#endif
 std::error_code ec;std::filesystem::remove(options.dataDirectory/"test.analysis",ec);std::filesystem::remove(options.dataDirectory/"analysis-example.penta-analysis",ec);std::filesystem::remove(options.dataDirectory,ec);
}
